import React from "react";

const DashBoard = () => {
  return (
    <>
      <div className="h-screen flex flex-col">
        {/* Navbar */}
        <nav className="bg-blue-600 text-white flex justify-between items-center p-4 shadow-md">
          <div className="flex space-x-6">
            <a href="#" className="hover:text-gray-200">
              Attendance
            </a>
            <a href="#" className="hover:text-gray-200">
              Result
            </a>
          </div>
          <button className="bg-red-500 px-4 py-2 rounded hover:bg-red-700">
            Logout
          </button>
        </nav>

        {/* Empty Page Content */}
        <div className="flex-1 bg-gray-100 flex justify-center items-center text-gray-500">
          Content goes here...
        </div>
      </div>
    </>
  );
};

export default DashBoard;
